<body>
<header class="topbar">
  <div class="brand">
    <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/004.png" width="48" height="52" alt="">
    <a class="btn" href="#" aria-label="Missing Dice home">Missing Dice</a>
  </div>
  <div class="nav-right">
    <a class="coffee btn" href="#">Buy me a coffee</a>
    <div class="mode-wrap">
      <button class="mode-toggle btn" id="modeToggle" type="button" aria-expanded="false">
        <span>Color modes</span><span class="arrow">⌄</span>
      </button>
      <div class="mode-menu" id="modeMenu">
        <button class="btn" type="button" data-mode="default">Default</button>
        <button class="btn" type="button" data-mode="warm">Warm</button>
        <button class="btn" type="button" data-mode="dark">Dark</button>
      </div>
    </div>
  </div>
</header>

<main>
  <section class="intro">
    <div class="intro-inner">
      <h1>Roll a D8</h1>
      <p>Use this too to roll any amount of <strong>8-sided dice.</strong></p>
      <p>For more options try our <a class="btn" href="#">all-purpose dice roller</a>.</p>
    </div>
  </section>

  <section class="controls-band striped">
    <div class="counter">
      <label for="diceCount">number of 8-sided dice:</label>
      <div class="stepper">
        <button class="btn" id="minus" type="button" aria-label="Decrease dice count">-</button>
        <input id="diceCount" type="number" min="1" max="99" value="1" aria-label="Number of 8-sided dice">
        <button class="btn" id="plus" type="button" aria-label="Increase dice count">+</button>
      </div>
    </div>
  </section>

  <section class="results" aria-live="polite">
    <div class="dice" id="diceDisplay"></div>
  </section>

  <section class="total-band">
    <div class="total-box">TOTAL : <strong id="total">7</strong></div>
  </section>

  <section class="roll-band striped">
    <button class="roll-button btn" id="roll" type="button">ROLL DICE</button>
  </section>
</main>

<script>
  const countInput = document.getElementById('diceCount');
  const diceDisplay = document.getElementById('diceDisplay');
  const totalDisplay = document.getElementById('total');
  let values = [7];
  let rollIndex = 0;

  const scriptedRolls = [
    [1, 5, 5, 1],
    [2, 1, 8, 3],
    [1, 7, 8, 6]
  ];

  function renderDice() {
    diceDisplay.replaceChildren();
    values.forEach(value => {
      const die = document.createElement('div');
      die.className = 'die';
      const number = document.createElement('span');
      number.textContent = value;
      die.appendChild(number);
      diceDisplay.appendChild(die);
    });
    totalDisplay.textContent = values.reduce((sum, value) => sum + value, 0);
  }

  function clampCount() {
    let amount = parseInt(countInput.value, 10);
    if (!Number.isFinite(amount)) amount = 1;
    amount = Math.max(1, Math.min(99, amount));
    countInput.value = amount;
    return amount;
  }

  document.getElementById('minus').addEventListener('click', () => {
    countInput.value = Math.max(1, clampCount() - 1);
  });

  document.getElementById('plus').addEventListener('click', () => {
    countInput.value = Math.min(99, clampCount() + 1);
  });

  countInput.addEventListener('change', clampCount);

  document.getElementById('roll').addEventListener('click', () => {
    const amount = clampCount();
    let next;
    if (amount === 4 && rollIndex < scriptedRolls.length) {
      next = scriptedRolls[rollIndex++];
    } else {
      next = Array.from({ length: amount }, () => Math.floor(Math.random() * 8) + 1);
    }
    values = next.slice(0, amount);
    while (values.length < amount) values.push(Math.floor(Math.random() * 8) + 1);
    renderDice();
  });

  const modeToggle = document.getElementById('modeToggle');
  const modeMenu = document.getElementById('modeMenu');
  modeToggle.addEventListener('click', () => {
    const open = modeMenu.classList.toggle('open');
    modeToggle.setAttribute('aria-expanded', String(open));
  });

  modeMenu.querySelectorAll('button').forEach(button => {
    button.addEventListener('click', () => {
      document.body.classList.remove('warm', 'dark');
      if (button.dataset.mode !== 'default') document.body.classList.add(button.dataset.mode);
      modeMenu.classList.remove('open');
      modeToggle.setAttribute('aria-expanded', 'false');
    });
  });

  document.addEventListener('click', event => {
    if (!event.target.closest('.mode-wrap')) {
      modeMenu.classList.remove('open');
      modeToggle.setAttribute('aria-expanded', 'false');
    }
  });

  renderDice();
</script>
</body>
</html>
